    private static void validateGenerateParenthesesTestCoverage(
            String name, JsonObject problemJson, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != GENERATE_PARENTHESES_PROBLEM_NUMBER) {
            return;
        }

        JsonArray tests = requireProblemArray(name, problemJson, "tests");
        Set<Integer> missingN = new HashSet<>(Set.of(1, 2, 3, 4, 5));

        for (JsonElement element : tests) {
            if (!element.isJsonObject()) {
                continue;
            }
            JsonObject test = element.getAsJsonObject();
            if (!test.has("input") || !test.get("input").isJsonPrimitive()
                    || !test.get("input").getAsJsonPrimitive().isString()
                    || !test.has("output") || !test.get("output").isJsonPrimitive()
                    || !test.get("output").getAsJsonPrimitive().isString()) {
                continue;
            }

            String input = compactOutsideDoubleQuotedText(test.get("input").getAsString());
            Matcher matcher = Pattern.compile("n=(\\d+)").matcher(input);
            if (!matcher.matches()) {
                continue;
            }

            int n = Integer.parseInt(matcher.group(1));
            if (!missingN.contains(n)) {
                continue;
            }

            Set<String> actual = parseStringArrayOutput(name, test.get("output").getAsString());
            if (actual.equals(expectedGenerateParentheses(n))) {
                missingN.remove(n);
            }
        }

        if (!missingN.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Generate Parentheses tests must include complete Catalan output sets for n=1, n=2, "
                    + "n=3, n=4, and n=5; missing or incorrect n values " + missingN);
        }
    }

