            hasEnumerationBaseline = hasEnumerationBaseline
                    || ((searchable.contains("enumerate") || searchable.contains("baseline"))
                    && containsNormalizedCode(normalizedRawCode, "for (int left = 0; left < nums.length; left++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int right = left; right < nums.length; right++)")
                    && containsNormalizedCode(normalizedRawCode, "minimum = Math.min(minimum, value)")
                    && containsNormalizedCode(normalizedRawCode, "if (minimum < minK || maximum > maxK)")
                    && containsNormalizedCode(normalizedRawCode, "answer++"));
