    private static String streamOfCharactersInput(List<String> words, String queryLetters) {
        StringBuilder operations = new StringBuilder("[\"StreamChecker\"");
        StringBuilder arguments = new StringBuilder("[[[");
        for (int i = 0; i < words.size(); i++) {
            if (i > 0) {
                arguments.append(", ");
            }
            arguments.append('"').append(words.get(i)).append('"');
        }
        arguments.append("]]");
        for (int i = 0; i < queryLetters.length(); i++) {
            operations.append(", \"query\"");
            arguments.append(", [\"").append(queryLetters.charAt(i)).append("\"]");
        }
        operations.append(']');
        arguments.append(']');
        return operations + "\n" + arguments;
    }

    private static String streamOfCharactersTestCaseKey(String input, String output) {
        return compactOutsideDoubleQuotedText(input) + "|" + compactOutsideDoubleQuotedText(output);
    }

    private static void validateStreamOfCharactersSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != STREAM_OF_CHARACTERS_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 5) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Stream of Characters should teach reverse trie suffix scanning, Aho-Corasick, "
                    + "forward trie active states, exact length-bucket suffix sets, and rolling hash verification");
        }

        boolean hasReverseTrie = false;
        boolean hasAhoCorasick = false;
        boolean hasForwardActiveStates = false;
        boolean hasLengthBuckets = false;
        boolean hasRollingHashVerification = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasReverseTrie = hasReverseTrie
                    || ((searchable.contains("reverse trie") || searchable.contains("reversed-word"))
                    && containsNormalizedCode(normalizedRawCode, "private final Node root = new Node()")
                    && containsNormalizedCode(normalizedRawCode, "suffix.deleteCharAt(0)")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = suffix.length() - 1; i >= 0; i--)"));
            hasAhoCorasick = hasAhoCorasick
                    || ((searchable.contains("aho") || searchable.contains("automaton"))
                    && containsNormalizedCode(normalizedRawCode, "private final int[][] next")
                    && containsNormalizedCode(normalizedRawCode, "private final int[] fail")
                    && containsNormalizedCode(normalizedRawCode, "output[node] = output[node] || output[fail[node]]")
                    && containsNormalizedCode(normalizedRawCode, "state = next[state][letter - 'a']"));
            hasForwardActiveStates = hasForwardActiveStates
                    || ((searchable.contains("active") || searchable.contains("forward trie"))
                    && containsNormalizedCode(normalizedRawCode, "private List<Node> active = new ArrayList<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "Set<Node> nextStates = Collections.newSetFromMap(new IdentityHashMap<>())")
                    && containsNormalizedCode(normalizedRawCode, "for (Node node : active)"));
            hasLengthBuckets = hasLengthBuckets
                    || ((searchable.contains("length-bucket") || searchable.contains("exact suffix"))
                    && containsNormalizedCode(normalizedRawCode,
                    "private final Map<Integer, Set<String>> wordsByLength = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode,
                    "String suffix = stream.substring(stream.length() - length)")
                    && containsNormalizedCode(normalizedRawCode, "entry.getValue().contains(suffix)"));
            hasRollingHashVerification = hasRollingHashVerification
                    || ((searchable.contains("rolling hash") || searchable.contains("exact verification"))
                    && containsNormalizedCode(normalizedRawCode, "private static final long BASE")
                    && containsNormalizedCode(normalizedRawCode,
                    "private final Map<Integer, Map<Long, List<String>>> wordsByLengthAndHash = new HashMap<>()")
                    && containsNormalizedCode(normalizedRawCode, "long hash = reversedHash(word)")
                    && containsNormalizedCode(normalizedRawCode, "matchesAny(candidates, length)"));
        }

        List<String> missing = new ArrayList<>();
        if (!hasReverseTrie) {
            missing.add("reverse trie suffix-scanning route");
        }
        if (!hasAhoCorasick) {
            missing.add("Aho-Corasick automaton route");
        }
        if (!hasForwardActiveStates) {
            missing.add("forward trie active-states route");
        }
        if (!hasLengthBuckets) {
            missing.add("exact length-bucket suffix-set route");
        }
        if (!hasRollingHashVerification) {
            missing.add("rolling hash with exact verification route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Stream of Characters solutions must include "
                    + String.join(", ", missing));
        }
    }

