    private static String escapeLargeMazeStraightWallInput() {
        StringBuilder input = new StringBuilder("blocked = [");
        for (int y = 0; y < 200; y++) {
            if (y > 0) {
                input.append(',');
            }
            input.append("[1,").append(y).append(']');
        }
        return input.append("], source = [0,0], target = [2,0]").toString();
    }

