    private static void validateParsingBooleanExpressionTestCoverage(
            String name, JsonObject problemJson, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != PARSING_BOOLEAN_EXPRESSION_PROBLEM_NUMBER) {
            return;
        }

        Set<String> requiredCases = new HashSet<>(List.of(
                parsingBooleanExpressionTestCaseKey("expression = \"t\"", "true"),
                parsingBooleanExpressionTestCaseKey("expression = \"f\"", "false"),
                parsingBooleanExpressionTestCaseKey("expression = \"&(|(f))\"", "false"),
                parsingBooleanExpressionTestCaseKey("expression = \"|(f,f,f,t)\"", "true"),
                parsingBooleanExpressionTestCaseKey("expression = \"!(&(f,t))\"", "true"),
                parsingBooleanExpressionTestCaseKey("expression = \"!(f)\"", "true"),
                parsingBooleanExpressionTestCaseKey("expression = \"&(t,t,t)\"", "true"),
                parsingBooleanExpressionTestCaseKey("expression = \"|(&(t,f,t),!(t))\"", "false"),
                parsingBooleanExpressionTestCaseKey(
                        "expression = \"&(|(f,t),!(f),&(t,t,!(f)))\"", "true"),
                parsingBooleanExpressionTestCaseKey(
                        "expression = \"|(f,!(t),&(t,f),|(f))\"", "false"),
                parsingBooleanExpressionTestCaseKey(
                        "expression = \"!(&(t,t,|(f,f)))\"", "true"),
                parsingBooleanExpressionTestCaseKey(
                        "expression = \"&(t,!(|(f,f)),|(&(t,t),!(t)))\"", "true"),
                parsingBooleanExpressionTestCaseKey(
                        "expression = \"|(&(t,!(f),|(f,f,t)),!(&(t,t,t)),&(t,t,!(|(f,f))))\"",
                        "true"),
                parsingBooleanExpressionTestCaseKey(parsingBooleanExpressionNestedNotInput(), "true"),
                parsingBooleanExpressionTestCaseKey(parsingBooleanExpressionLongOrInput(), "true"),
                parsingBooleanExpressionTestCaseKey(parsingBooleanExpressionLongAndInput(), "true")));

        JsonArray tests = requireProblemArray(name, problemJson, "tests");
        for (JsonElement element : tests) {
            if (!element.isJsonObject()) {
                continue;
            }
            JsonObject test = element.getAsJsonObject();
            String input = compactOutsideDoubleQuotedText(requireProblemString(name, test, "input"));
            String output = compactOutsideDoubleQuotedText(requireProblemString(name, test, "output"));
            requiredCases.remove(parsingBooleanExpressionTestCaseKey(input, output));
        }

        if (!requiredCases.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Parsing A Boolean Expression tests must cover literals, canonical examples, "
                    + "short-circuit-shaped branches, deep unary nesting, and long operand lists; missing "
                    + requiredCases);
        }
    }

    private static String parsingBooleanExpressionNestedNotInput() {
        String expression = "t";
        for (int i = 0; i < 50; i++) {
            expression = "!(" + expression + ")";
        }
        return "expression = \"" + expression + "\"";
    }

    private static String parsingBooleanExpressionLongOrInput() {
        StringBuilder input = new StringBuilder("expression = \"|(");
        for (int i = 0; i < 120; i++) {
            if (i > 0) {
                input.append(',');
            }
            input.append('f');
        }
        return input.append(",t)\"").toString();
    }

    private static String parsingBooleanExpressionLongAndInput() {
        StringBuilder input = new StringBuilder("expression = \"&(");
        for (int i = 0; i < 120; i++) {
            if (i > 0) {
                input.append(',');
            }
            input.append('t');
        }
        return input.append(",!(f))\"").toString();
    }

    private static String parsingBooleanExpressionTestCaseKey(String input, String output) {
        return compactOutsideDoubleQuotedText(input) + "|" + compactOutsideDoubleQuotedText(output);
    }

    private static void validateParsingBooleanExpressionSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != PARSING_BOOLEAN_EXPRESSION_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 5) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Parsing A Boolean Expression should teach character stack reduction, recursive descent, "
                    + "operator frame stack, short-circuit recursive parsing, and primitive array frame routes");
        }

        boolean hasCharacterStack = false;
        boolean hasRecursiveDescent = false;
        boolean hasOperatorFrameStack = false;
        boolean hasShortCircuitParser = false;
        boolean hasPrimitiveArrayFrameMachine = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasCharacterStack = hasCharacterStack
                    || (searchable.contains("character stack")
                    && containsNormalizedCode(normalizedRawCode, "Deque<Character> stack = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "while (stack.peek() != '(')")
                    && containsNormalizedCode(normalizedRawCode,
                    "stack.push(reduce(operator, hasTrue, hasFalse) ? 't' : 'f')"));
            hasRecursiveDescent = hasRecursiveDescent
                    || (searchable.contains("recursive descent")
                    && containsNormalizedCode(normalizedRawCode, "private int index")
                    && containsNormalizedCode(normalizedRawCode, "return parse(expression)")
                    && containsNormalizedCode(normalizedRawCode, "while (expression.charAt(index) != ')')")
                    && containsNormalizedCode(normalizedRawCode, "index += 2"));
            hasOperatorFrameStack = hasOperatorFrameStack
                    || (searchable.contains("operator frame")
                    && containsNormalizedCode(normalizedRawCode, "Deque<Frame> frames = new ArrayDeque<>()")
                    && containsNormalizedCode(normalizedRawCode, "private static final class Frame")
                    && containsNormalizedCode(normalizedRawCode, "frames.peek().add(result)")
                    && containsNormalizedCode(normalizedRawCode, "frames.pop().value()"));
            hasShortCircuitParser = hasShortCircuitParser
                    || (searchable.contains("short-circuit")
                    && containsNormalizedCode(normalizedRawCode, "boolean decided = false")
                    && containsNormalizedCode(normalizedRawCode, "skipExpression(expression)")
                    && containsNormalizedCode(normalizedRawCode, "int depth = 1")
                    && containsNormalizedCode(normalizedRawCode, "operator == '&' && !value"));
            hasPrimitiveArrayFrameMachine = hasPrimitiveArrayFrameMachine
                    || (searchable.contains("primitive array")
                    && containsNormalizedCode(normalizedRawCode, "char[] operators = new char[n]")
                    && containsNormalizedCode(normalizedRawCode, "int[] masks = new int[n]")
                    && containsNormalizedCode(normalizedRawCode, "masks[top] |= result ? 2 : 1")
                    && containsNormalizedCode(normalizedRawCode, "result = reduce(operators[top], masks[top])"));
        }

        List<String> missing = new ArrayList<>();
        if (!hasCharacterStack) {
            missing.add("character-stack reduction route");
        }
        if (!hasRecursiveDescent) {
            missing.add("recursive-descent parser route");
        }
        if (!hasOperatorFrameStack) {
            missing.add("operator-frame stack route");
        }
        if (!hasShortCircuitParser) {
            missing.add("short-circuit recursive parser route");
        }
        if (!hasPrimitiveArrayFrameMachine) {
            missing.add("primitive-array frame machine route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Parsing A Boolean Expression solutions must include "
                    + String.join(", ", missing));
        }
    }

