    private static void validateLongestChunkedPalindromeSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != LONGEST_CHUNKED_PALINDROME_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 5) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Longest Chunked Palindrome Decomposition should teach shortest-border greedy, "
                    + "rolling-hash greedy, recursive border matching, interval DP with LCP, and KMP "
                    + "prefix-function border peeling");
        }

        boolean hasGreedyShortestBorder = false;
        boolean hasRollingHashGreedy = false;
        boolean hasRecursiveBorderMatch = false;
        boolean hasIntervalDpWithLcp = false;
        boolean hasPrefixFunctionPeeling = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasGreedyShortestBorder = hasGreedyShortestBorder
                    || (searchable.contains("greedy") && searchable.contains("shortest")
                    && containsNormalizedCode(normalizedRawCode, "StringBuilder left = new StringBuilder()")
                    && containsNormalizedCode(normalizedRawCode, "right.insert(0, text.charAt(rightStart--))")
                    && containsNormalizedCode(normalizedRawCode, "answer += 2"));
            hasRollingHashGreedy = hasRollingHashGreedy
                    || (searchable.contains("rolling hash")
                    && containsNormalizedCode(normalizedRawCode, "long leftHash1 = 0, leftHash2 = 0")
                    && containsNormalizedCode(normalizedRawCode, "power1 = power1 * BASE % MOD1")
                    && containsNormalizedCode(normalizedRawCode, "matches(text, leftStart, j, currentLength)"));
            hasRecursiveBorderMatch = hasRecursiveBorderMatch
                    || (searchable.contains("recursive") && searchable.contains("border")
                    && containsNormalizedCode(normalizedRawCode, "return solve(text, 0, text.length() - 1)")
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int length = 1; length <= maxLength; length++)")
                    && containsNormalizedCode(normalizedRawCode,
                    "return 2 + solve(text, left + length, right - length)"));
            hasIntervalDpWithLcp = hasIntervalDpWithLcp
                    || ((searchable.contains("interval dp") || searchable.contains("lcp"))
                    && (containsNormalizedCode(normalizedRawCode, "int[][] lcp = new int[n + 1][n + 1]")
                            || containsNormalizedCode(normalizedRawCode, "lcp = new int[n + 1][n + 1]"))
                    && containsNormalizedCode(normalizedRawCode, "memo = new int[n][n]")
                    && containsNormalizedCode(normalizedRawCode,
                    "best = Math.max(best, 2 + dp(left + length, right - length))"));
            hasPrefixFunctionPeeling = hasPrefixFunctionPeeling
                    || ((searchable.contains("prefix-function") || searchable.contains("kmp"))
                    && containsNormalizedCode(normalizedRawCode, "int[] pi = prefixFunction(segment)")
                    && containsNormalizedCode(normalizedRawCode,
                    "for (int length = pi[segment.length() - 1]; length > 0; length = pi[length - 1])")
                    && containsNormalizedCode(normalizedRawCode, "return best"));
        }

        List<String> missing = new ArrayList<>();
        if (!hasGreedyShortestBorder) {
            missing.add("shortest-border greedy scan route");
        }
        if (!hasRollingHashGreedy) {
            missing.add("rolling-hash greedy scan route");
        }
        if (!hasRecursiveBorderMatch) {
            missing.add("recursive shortest-border match route");
        }
        if (!hasIntervalDpWithLcp) {
            missing.add("interval DP with LCP table route");
        }
        if (!hasPrefixFunctionPeeling) {
            missing.add("KMP prefix-function border peeling route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Longest Chunked Palindrome Decomposition solutions must include "
                    + String.join(", ", missing));
        }
    }

