    private static void validateDesignUndergroundSystemTestCoverage(
            String name, JsonObject problemJson, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT || problemNumber != DESIGN_UNDERGROUND_SYSTEM_PROBLEM_NUMBER) {
            return;
        }

        JsonArray tests = requireProblemArray(name, problemJson, "tests");
        if (tests.size() < 8) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Design Underground System should include the canonical example, route updates, "
                    + "direction separation, route-key collision safety, passenger id reuse, active-trip "
                    + "exclusion, case-sensitive station names, and aggregate overflow pressure");
        }

        Set<String> requiredCases = new HashSet<>(List.of(
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkIn\",\"checkIn\",\"checkOut\",\"checkOut\",\"checkOut\",\"getAverageTime\",\"getAverageTime\",\"checkIn\",\"getAverageTime\",\"checkOut\",\"getAverageTime\"]\n"
                                + "[[],[45,\"Leyton\",3],[32,\"Paradise\",8],[27,\"Leyton\",10],[45,\"Waterloo\",15],[27,\"Waterloo\",20],[32,\"Cambridge\",22],[\"Paradise\",\"Cambridge\"],[\"Leyton\",\"Waterloo\"],[10,\"Leyton\",24],[\"Leyton\",\"Waterloo\"],[10,\"Waterloo\",38],[\"Leyton\",\"Waterloo\"]]",
                        "[null,null,null,null,null,null,null,14.00000,11.00000,null,11.00000,null,12.00000]"),
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkOut\",\"getAverageTime\",\"checkIn\",\"checkIn\",\"checkOut\",\"getAverageTime\",\"checkOut\",\"getAverageTime\",\"getAverageTime\"]\n"
                                + "[[],[1,\"A\",3],[1,\"B\",13],[\"A\",\"B\"],[2,\"A\",20],[3,\"A\",22],[2,\"B\",30],[\"A\",\"B\"],[3,\"C\",32],[\"A\",\"C\"],[\"A\",\"B\"]]",
                        "[null,null,null,10.00000,null,null,null,10.00000,null,10.00000,10.00000]"),
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkOut\",\"checkIn\",\"checkOut\",\"getAverageTime\",\"getAverageTime\"]\n"
                                + "[[],[1,\"A\",1],[1,\"B\",11],[2,\"B\",20],[2,\"A\",24],[\"A\",\"B\"],[\"B\",\"A\"]]",
                        "[null,null,null,null,null,10.00000,4.00000]"),
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkOut\",\"checkIn\",\"checkOut\",\"getAverageTime\",\"getAverageTime\"]\n"
                                + "[[],[1,\"A\",1],[1,\"BC\",11],[2,\"AB\",20],[2,\"C\",50],[\"A\",\"BC\"],[\"AB\",\"C\"]]",
                        "[null,null,null,null,null,10.00000,30.00000]"),
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkOut\",\"checkIn\",\"checkOut\",\"getAverageTime\"]\n"
                                + "[[],[7,\"Start\",5],[7,\"End\",15],[7,\"Start\",20],[7,\"End\",35],[\"Start\",\"End\"]]",
                        "[null,null,null,null,null,12.50000]"),
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkOut\",\"checkIn\",\"getAverageTime\",\"checkOut\",\"getAverageTime\"]\n"
                                + "[[],[1,\"A\",1],[1,\"B\",6],[2,\"A\",10],[\"A\",\"B\"],[2,\"B\",20],[\"A\",\"B\"]]",
                        "[null,null,null,null,5.00000,null,7.50000]"),
                designUndergroundSystemTestCaseKey(
                        "[\"UndergroundSystem\",\"checkIn\",\"checkOut\",\"checkIn\",\"checkOut\",\"getAverageTime\",\"getAverageTime\"]\n"
                                + "[[],[1,\"a1\",2],[1,\"A1\",9],[2,\"A1\",10],[2,\"a1\",18],[\"a1\",\"A1\"],[\"A1\",\"a1\"]]",
                        "[null,null,null,null,null,7.00000,8.00000]")));

        boolean hasOverflowPressure = false;
        for (JsonElement element : tests) {
            if (!element.isJsonObject()) {
                continue;
            }
            JsonObject test = element.getAsJsonObject();
            String input = requireProblemString(name, test, "input");
            String output = requireProblemString(name, test, "output");
            requiredCases.remove(designUndergroundSystemTestCaseKey(input, output));
            hasOverflowPressure = hasOverflowPressure
                    || (input.contains("\"OverflowStart\"")
                    && input.contains("\"OverflowEnd\"")
                    && countNeedleOccurrences(input, "\"checkIn\"") >= 2150
                    && countNeedleOccurrences(input, "\"checkOut\"") >= 2150
                    && output.contains("999999.00000"));
        }

        if (!requiredCases.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Design Underground System tests must cover route updates, direction separation, "
                    + "route-key collisions, passenger id reuse, active-trip exclusion, and station-name "
                    + "case sensitivity; missing " + requiredCases);
        }
        if (!hasOverflowPressure) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Design Underground System tests must include many overlapping trips on one route "
                    + "so int-based aggregate totals are rejected");
        }
    }

    private static String designUndergroundSystemTestCaseKey(String input, String output) {
        return compactOutsideDoubleQuotedText(input) + "|" + compactOutsideDoubleQuotedText(output);
    }

    private static int countNeedleOccurrences(String value, String needle) {
        int count = 0;
        int index = 0;
        while ((index = value.indexOf(needle, index)) >= 0) {
            count++;
            index += needle.length();
        }
        return count;
    }

