    private static void validateDesignGraphShortestPathSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != DESIGN_GRAPH_SHORTEST_PATH_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 5) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Design Graph With Shortest Path Calculator should teach adjacency-list Dijkstra, "
                    + "dense-matrix Dijkstra, incremental Floyd-Warshall, Bellman-Ford, and cached Dijkstra");
        }

        boolean hasAdjacencyListDijkstra = false;
        boolean hasDenseMatrixDijkstra = false;
        boolean hasIncrementalFloydWarshall = false;
        boolean hasBellmanFord = false;
        boolean hasCachedDijkstra = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasAdjacencyListDijkstra = hasAdjacencyListDijkstra
                    || searchable.contains("adjacency list")
                    && containsNormalizedCode(normalizedRawCode, "List<int[]>[] adj")
                    && containsNormalizedCode(normalizedRawCode, "PriorityQueue<int[]> heap")
                    && containsNormalizedCode(normalizedRawCode, "heap.offer(new int[]{node1, 0})")
                    && containsNormalizedCode(normalizedRawCode, "if (node == node2)");
            hasDenseMatrixDijkstra = hasDenseMatrixDijkstra
                    || searchable.contains("dense")
                    && containsNormalizedCode(normalizedRawCode, "int[][] cost")
                    && containsNormalizedCode(normalizedRawCode, "boolean[] used")
                    && containsNormalizedCode(normalizedRawCode, "for (int next = 0; next < n; next++)")
                    && containsNormalizedCode(normalizedRawCode, "cost[edge[0]][edge[1]] = edge[2]");
            hasIncrementalFloydWarshall = hasIncrementalFloydWarshall
                    || searchable.contains("floyd")
                    && containsNormalizedCode(normalizedRawCode, "int[][] dist")
                    && containsNormalizedCode(normalizedRawCode, "for (int mid = 0; mid < n; mid++)")
                    && containsNormalizedCode(normalizedRawCode, "dist[from][u] + w + dist[v][to]")
                    && containsNormalizedCode(normalizedRawCode, "return dist[node1][node2] == INF ? -1 : dist[node1][node2]");
            hasBellmanFord = hasBellmanFord
                    || searchable.contains("bellman-ford")
                    && containsNormalizedCode(normalizedRawCode, "List<int[]> edges")
                    && containsNormalizedCode(normalizedRawCode, "for (int pass = 0; pass < n - 1; pass++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int[] edge : edges)")
                    && containsNormalizedCode(normalizedRawCode, "if (!changed)");
            hasCachedDijkstra = hasCachedDijkstra
                    || searchable.contains("cached")
                    && containsNormalizedCode(normalizedRawCode, "Map<Integer, int[]> distanceCache")
                    && containsNormalizedCode(normalizedRawCode, "distanceCache.clear()")
                    && containsNormalizedCode(normalizedRawCode, "distanceCache.computeIfAbsent(node1, this::runDijkstraFrom)")
                    && containsNormalizedCode(normalizedRawCode, "private int[] runDijkstraFrom(int source)");
        }

        List<String> missing = new ArrayList<>();
        if (!hasAdjacencyListDijkstra) {
            missing.add("adjacency-list Dijkstra route");
        }
        if (!hasDenseMatrixDijkstra) {
            missing.add("dense-matrix Dijkstra route");
        }
        if (!hasIncrementalFloydWarshall) {
            missing.add("incremental Floyd-Warshall route");
        }
        if (!hasBellmanFord) {
            missing.add("Bellman-Ford edge-list route");
        }
        if (!hasCachedDijkstra) {
            missing.add("cached Dijkstra route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Design Graph With Shortest Path Calculator solutions must include "
                    + String.join(", ", missing));
        }
    }

