    private static void validateRangeSumQueryImmutableSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != RANGE_SUM_QUERY_IMMUTABLE_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 5) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Range Sum Query - Immutable should teach prefix sums, Fenwick tree, "
                    + "static segment tree, block decomposition, and direct scan baseline");
        }

        boolean hasPrefixSum = false;
        boolean hasFenwickTree = false;
        boolean hasStaticSegmentTree = false;
        boolean hasBlockDecomposition = false;
        boolean hasDirectScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasPrefixSum = hasPrefixSum
                    || searchable.contains("prefix sum")
                    && containsNormalizedCode(normalizedRawCode, "int[] prefix")
                    && containsNormalizedCode(normalizedRawCode, "prefix[i + 1] = prefix[i] + nums[i]")
                    && containsNormalizedCode(normalizedRawCode, "return prefix[right + 1] - prefix[left]");
            hasFenwickTree = hasFenwickTree
                    || searchable.contains("fenwick")
                    && containsNormalizedCode(normalizedRawCode, "int[] bit")
                    && containsNormalizedCode(normalizedRawCode, "i += i & -i")
                    && containsNormalizedCode(normalizedRawCode, "i -= i & -i")
                    && containsNormalizedCode(normalizedRawCode, "return prefix(right + 1) - prefix(left)");
            hasStaticSegmentTree = hasStaticSegmentTree
                    || searchable.contains("segment tree")
                    && containsNormalizedCode(normalizedRawCode, "int[] tree")
                    && containsNormalizedCode(normalizedRawCode, "build(1, 0, n - 1, nums)")
                    && containsNormalizedCode(normalizedRawCode, "query(1, 0, n - 1, left, right)")
                    && containsNormalizedCode(normalizedRawCode, "right < start || end < left");
            hasBlockDecomposition = hasBlockDecomposition
                    || searchable.contains("block")
                    && containsNormalizedCode(normalizedRawCode, "int[] blockSum")
                    && containsNormalizedCode(normalizedRawCode, "blockSize = (int) Math.ceil(Math.sqrt(nums.length))")
                    && containsNormalizedCode(normalizedRawCode, "blockSum[i / blockSize] += nums[i]")
                    && containsNormalizedCode(normalizedRawCode, "for (int block = startBlock + 1; block < endBlock; block++)");
            hasDirectScan = hasDirectScan
                    || solutionName.toLowerCase(Locale.ROOT).contains("direct scan")
                    && containsNormalizedCode(normalizedRawCode, "nums.clone()")
                    && containsNormalizedCode(normalizedRawCode, "for (int i = left; i <= right; i++)")
                    && containsNormalizedCode(normalizedRawCode, "sum += nums[i]");
        }

        List<String> missing = new ArrayList<>();
        if (!hasPrefixSum) {
            missing.add("prefix-sum route");
        }
        if (!hasFenwickTree) {
            missing.add("Fenwick tree route");
        }
        if (!hasStaticSegmentTree) {
            missing.add("static segment-tree route");
        }
        if (!hasBlockDecomposition) {
            missing.add("block-decomposition route");
        }
        if (!hasDirectScan) {
            missing.add("direct-scan baseline route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Range Sum Query - Immutable solutions must include " + String.join(", ", missing));
        }
    }

