    private static void validateRangeSumQuery2dImmutableSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != RANGE_SUM_QUERY_2D_IMMUTABLE_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 5) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Range Sum Query 2D - Immutable should teach 2D prefix sums, row-wise "
                    + "prefix sums, column-wise prefix sums, static 2D Fenwick tree, and direct "
                    + "region scan baseline");
        }

        boolean hasTwoDimensionalPrefix = false;
        boolean hasRowWisePrefix = false;
        boolean hasColumnWisePrefix = false;
        boolean hasTwoDimensionalFenwick = false;
        boolean hasDirectRegionScan = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasTwoDimensionalPrefix = hasTwoDimensionalPrefix
                    || searchable.contains("2d prefix")
                    && containsNormalizedCode(normalizedRawCode, "int[][] prefix")
                    && containsNormalizedCode(normalizedRawCode, "prefix = new int[m + 1][n + 1]")
                    && containsNormalizedCode(normalizedRawCode, "matrix[row - 1][col - 1]")
                    && containsNormalizedCode(normalizedRawCode, "return prefix[row2 + 1][col2 + 1]");
            hasRowWisePrefix = hasRowWisePrefix
                    || searchable.contains("row-wise")
                    && containsNormalizedCode(normalizedRawCode, "int[][] rowPrefix")
                    && containsNormalizedCode(normalizedRawCode, "rowPrefix[row][col + 1] = rowPrefix[row][col] + matrix[row][col]")
                    && containsNormalizedCode(normalizedRawCode, "for (int row = row1; row <= row2; row++)")
                    && containsNormalizedCode(normalizedRawCode, "rowPrefix[row][col2 + 1] - rowPrefix[row][col1]");
            hasColumnWisePrefix = hasColumnWisePrefix
                    || searchable.contains("column-wise")
                    && containsNormalizedCode(normalizedRawCode, "int[][] colPrefix")
                    && containsNormalizedCode(normalizedRawCode, "colPrefix[row + 1][col] = colPrefix[row][col] + matrix[row][col]")
                    && containsNormalizedCode(normalizedRawCode, "for (int col = col1; col <= col2; col++)")
                    && containsNormalizedCode(normalizedRawCode, "colPrefix[row2 + 1][col] - colPrefix[row1][col]");
            hasTwoDimensionalFenwick = hasTwoDimensionalFenwick
                    || searchable.contains("fenwick")
                    && containsNormalizedCode(normalizedRawCode, "int[][] bit")
                    && containsNormalizedCode(normalizedRawCode, "r += r & -r")
                    && containsNormalizedCode(normalizedRawCode, "c += c & -c")
                    && containsNormalizedCode(normalizedRawCode, "r -= r & -r")
                    && containsNormalizedCode(normalizedRawCode, "c -= c & -c");
            hasDirectRegionScan = hasDirectRegionScan
                    || solutionName.toLowerCase(Locale.ROOT).contains("direct region scan")
                    && containsNormalizedCode(normalizedRawCode, "matrix[row].clone()")
                    && containsNormalizedCode(normalizedRawCode, "for (int row = row1; row <= row2; row++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int col = col1; col <= col2; col++)")
                    && containsNormalizedCode(normalizedRawCode, "sum += matrix[row][col]");
        }

        List<String> missing = new ArrayList<>();
        if (!hasTwoDimensionalPrefix) {
            missing.add("2D prefix-sum route");
        }
        if (!hasRowWisePrefix) {
            missing.add("row-wise prefix-sum route");
        }
        if (!hasColumnWisePrefix) {
            missing.add("column-wise prefix-sum route");
        }
        if (!hasTwoDimensionalFenwick) {
            missing.add("static 2D Fenwick tree route");
        }
        if (!hasDirectRegionScan) {
            missing.add("direct region scan baseline route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Range Sum Query 2D - Immutable solutions must include " + String.join(", ", missing));
        }
    }

