    private static void validateSubarrayProductLessThanKSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT
                || problemNumber != SUBARRAY_PRODUCT_LESS_THAN_K_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 4) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Subarray Product should teach sliding-window product, reset-aware windowing, "
                    + "prefix-log binary search, and brute-force early break");
        }

        boolean hasSlidingWindow = false;
        boolean hasResetWindow = false;
        boolean hasPrefixLogBinarySearch = false;
        boolean hasBruteForceEarlyBreak = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasSlidingWindow = hasSlidingWindow
                    || (searchable.contains("sliding window product")
                    && containsNormalizedCode(normalizedRawCode, "if (k <= 1) return 0")
                    && containsNormalizedCode(normalizedRawCode, "product *= nums[right]")
                    && containsNormalizedCode(normalizedRawCode, "while (product >= k)")
                    && containsNormalizedCode(normalizedRawCode, "product /= nums[left]")
                    && containsNormalizedCode(normalizedRawCode, "answer += right - left + 1"));
            hasResetWindow = hasResetWindow
                    || (searchable.contains("reset")
                    && containsNormalizedCode(normalizedRawCode, "if (nums[right] >= k)")
                    && containsNormalizedCode(normalizedRawCode, "product = 1L")
                    && containsNormalizedCode(normalizedRawCode, "left = right + 1")
                    && containsNormalizedCode(normalizedRawCode, "continue"));
            hasPrefixLogBinarySearch = hasPrefixLogBinarySearch
                    || ((searchable.contains("log") || searchable.contains("binary search"))
                    && containsNormalizedCode(normalizedRawCode, "double[] prefix = new double[n + 1]")
                    && containsNormalizedCode(normalizedRawCode, "Math.log(nums[i])")
                    && containsNormalizedCode(normalizedRawCode, "Math.log(k)")
                    && containsNormalizedCode(normalizedRawCode, "upperBound(prefix, limit)")
                    && containsNormalizedCode(normalizedRawCode, "values[mid] <= target"));
            hasBruteForceEarlyBreak = hasBruteForceEarlyBreak
                    || ((searchable.contains("brute") || searchable.contains("early break"))
                    && containsNormalizedCode(normalizedRawCode, "for (int start = 0; start < nums.length; start++)")
                    && containsNormalizedCode(normalizedRawCode, "for (int end = start; end < nums.length; end++)")
                    && containsNormalizedCode(normalizedRawCode, "product *= nums[end]")
                    && containsNormalizedCode(normalizedRawCode, "if (product >= k)")
                    && containsNormalizedCode(normalizedRawCode, "break")
                    && containsNormalizedCode(normalizedRawCode, "answer++"));
        }

        List<String> missing = new ArrayList<>();
        if (!hasSlidingWindow) {
            missing.add("sliding-window product route");
        }
        if (!hasResetWindow) {
            missing.add("reset-aware sliding-window route");
        }
        if (!hasPrefixLogBinarySearch) {
            missing.add("prefix-log binary-search route");
        }
        if (!hasBruteForceEarlyBreak) {
            missing.add("brute-force early-break route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Subarray Product solutions must include " + String.join(", ", missing));
        }
    }

