    private static void validateTrimBinarySearchTreeSolutionSet(
            String name, JsonArray solutions, int problemNumber, int totalProblems) throws IOException {
        if (totalProblems != OFFICIAL_PROBLEM_COUNT || problemNumber != TRIM_BINARY_SEARCH_TREE_PROBLEM_NUMBER) {
            return;
        }
        if (solutions.size() < 4) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Trim a Binary Search Tree should teach recursive pruning, iterative side relinking, "
                    + "stack-based rewiring, and non-mutating cloned trimming");
        }

        boolean hasRecursiveRangePruning = false;
        boolean hasIterativeRelinking = false;
        boolean hasStackRewire = false;
        boolean hasClonedTrim = false;

        for (int i = 0; i < solutions.size(); i++) {
            JsonObject solution = solutions.get(i).getAsJsonObject();
            String solutionName = requireProblemSolutionString(name, i, solution, "name");
            String description = requireProblemSolutionString(name, i, solution, "description");
            String code = requireProblemSolutionString(name, i, solution, "code");
            String searchable = (solutionName + "\n" + description).toLowerCase(Locale.ROOT);
            String normalizedRawCode = normalizeCode(code).toLowerCase(Locale.ROOT);

            hasRecursiveRangePruning = hasRecursiveRangePruning
                    || ((searchable.contains("recursive") || searchable.contains("pruning"))
                    && containsNormalizedCode(normalizedRawCode, "return trimBST(root.right, low, high)")
                    && containsNormalizedCode(normalizedRawCode, "root.left = trimBST(root.left, low, high)")
                    && !containsNormalizedCode(normalizedRawCode, "new TreeNode(root.val)"));
            hasIterativeRelinking = hasIterativeRelinking
                    || ((searchable.contains("iterative") || searchable.contains("relink"))
                    && containsNormalizedCode(normalizedRawCode,
                    "while (root != null && (root.val < low || root.val > high))")
                    && containsNormalizedCode(normalizedRawCode, "node.left = node.left.right")
                    && containsNormalizedCode(normalizedRawCode, "node.right = node.right.left")
                    && !containsNormalizedCode(normalizedRawCode, "java.util.Deque<TreeNode> stack"));
            hasStackRewire = hasStackRewire
                    || ((searchable.contains("stack") || searchable.contains("rewire"))
                    && containsNormalizedCode(normalizedRawCode, "java.util.Deque<TreeNode> stack")
                    && containsNormalizedCode(normalizedRawCode, "stack.push(root)")
                    && containsNormalizedCode(normalizedRawCode, "TreeNode node = stack.pop()"));
            hasClonedTrim = hasClonedTrim
                    || ((searchable.contains("clone") || searchable.contains("non-mutating"))
                    && containsNormalizedCode(normalizedRawCode, "TreeNode kept = new TreeNode(root.val)")
                    && containsNormalizedCode(normalizedRawCode, "kept.left = trimBST(root.left, low, high)")
                    && containsNormalizedCode(normalizedRawCode, "kept.right = trimBST(root.right, low, high)"));
        }

        List<String> missing = new ArrayList<>();
        if (!hasRecursiveRangePruning) {
            missing.add("recursive range-pruning route");
        }
        if (!hasIterativeRelinking) {
            missing.add("iterative root and side relinking route");
        }
        if (!hasStackRewire) {
            missing.add("stack-based rewire traversal route");
        }
        if (!hasClonedTrim) {
            missing.add("non-mutating cloned trim route");
        }
        if (!missing.isEmpty()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": Trim a Binary Search Tree solutions must include " + String.join(", ", missing));
        }
    }

