    private static int minimumReferenceSolutions(int problemNumber, int totalProblems) {
        if (problemNumber <= Math.min(FOUNDATIONAL_PROBLEM_COUNT, totalProblems)) {
            return MIN_FOUNDATIONAL_REFERENCE_SOLUTIONS;
        }
        return MIN_REFERENCE_SOLUTIONS;
    }

    private static String requireProblemSolutionString(String name, int index, JsonObject solution, String field)
            throws IOException {
        if (!solution.has(field)
                || !solution.get(field).isJsonPrimitive()
                || !solution.get(field).getAsJsonPrimitive().isString()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": solutions[" + index + "]." + field + " must be a string");
        }
        String value = solution.get(field).getAsString();
        if (value.isBlank()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": solutions[" + index + "]." + field + " must not be blank");
        }
        return value;
    }

    private static void validateSolutionComplexity(String name, int index, JsonObject solution, String description)
            throws IOException {
        boolean markdownComplexity = description.contains("## Complexity Analysis")
                && description.contains("Time Complexity")
                && description.contains("Space Complexity");
        String timeComplexity = optionalProblemSolutionString(name, index, solution, "timeComplexity");
        String spaceComplexity = optionalProblemSolutionString(name, index, solution, "spaceComplexity");
        boolean fieldComplexity = timeComplexity != null && spaceComplexity != null;

        if (!markdownComplexity && !fieldComplexity) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": solutions[" + index + "] must include explicit time and space complexity metadata");
        }
        if (timeComplexity != null || spaceComplexity != null) {
            if (timeComplexity == null || spaceComplexity == null) {
                throw new IOException("Invalid official problem JSON for " + name
                        + ": solutions[" + index + "] must provide timeComplexity and spaceComplexity together");
            }
            if (!COMPLEXITY_NOTATION.matcher(timeComplexity).matches()) {
                throw new IOException("Invalid official problem JSON for " + name
                        + ": solutions[" + index + "].timeComplexity must use Big-O notation");
            }
            if (!COMPLEXITY_NOTATION.matcher(spaceComplexity).matches()) {
                throw new IOException("Invalid official problem JSON for " + name
                        + ": solutions[" + index + "].spaceComplexity must use Big-O notation");
            }
        }
    }

    private static String optionalProblemSolutionString(String name, int index, JsonObject solution, String field)
            throws IOException {
        if (!solution.has(field)) {
            return null;
        }
        if (!solution.get(field).isJsonPrimitive()
                || !solution.get(field).getAsJsonPrimitive().isString()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": solutions[" + index + "]." + field + " must be a string when present");
        }
        String value = solution.get(field).getAsString();
        if (value.isBlank()) {
            throw new IOException("Invalid official problem JSON for " + name
                    + ": solutions[" + index + "]." + field + " must not be blank when present");
        }
        return value;
    }

    private static String normalizeCode(String code) {
        return code.replaceAll("\\s+", "");
    }

    private static boolean containsNormalizedCode(String normalizedCode, String expectedSnippet) {
        return normalizedCode.contains(normalizeCode(expectedSnippet).toLowerCase(Locale.ROOT));
    }

    private static String normalizedInputCase(String input) {
        return input.replaceAll("\\s+", "");
    }

    private static String stripJavaCommentsAndLiterals(String code) {
        String withoutComments = code
                .replaceAll("/\\*[\\s\\S]*?\\*/", " ")
                .replaceAll("//[^\\n\\r]*", " ");
        return JAVA_CHAR_LITERAL.matcher(
                JAVA_STRING_LITERAL.matcher(withoutComments).replaceAll("\"\"")
        ).replaceAll("''");
    }

    private static String normalizeStructuralCode(String code) {
        String withoutComments = stripJavaCommentsAndLiterals(code);
        String withoutLiterals = JAVA_NUMBER_LITERAL.matcher(
                withoutComments
        ).replaceAll("0");

        Matcher matcher = JAVA_TOKEN.matcher(withoutLiterals);
        StringBuilder normalized = new StringBuilder(withoutLiterals.length());
        while (matcher.find()) {
            String token = matcher.group();
            if (isJavaIdentifier(token) && !JAVA_KEYWORDS.contains(token)) {
                normalized.append("ID");
            } else {
                normalized.append(token);
            }
        }
        return normalized.toString();
    }

    private static boolean isJavaIdentifier(String token) {
        if (token.isEmpty() || !Character.isJavaIdentifierStart(token.charAt(0))) {
            return false;
        }
        for (int i = 1; i < token.length(); i++) {
            if (!Character.isJavaIdentifierPart(token.charAt(i))) {
                return false;
            }
        }
        return true;
    }

    private static void validatePromptImageReferences(List<DownloadedProblem> problems, Set<String> manifestImages)
            throws IOException {
        Set<String> referencedImages = new HashSet<>();
        for (DownloadedProblem problem : problems) {
            for (Problem.Visual visual : problem.problem().getVisuals()) {
                String normalized = ProblemAssetResolver.normalizeImagePath(visual.file())
                        .orElseThrow(() -> new IOException("Invalid official prompt image reference in "
                                + problem.name() + ": " + visual.file()));
                validatePromptDiagramMetadata(problem.name(), normalized, visual.caption());
                referencedImages.add(normalized);
                if (!manifestImages.contains(normalized)) {
                    throw new IOException("Invalid repository manifest: prompt image " + normalized
                            + " referenced by " + problem.name() + " is missing from manifest");
                }
            }
        }

        List<String> unreferencedImages = manifestImages.stream()
                .filter(image -> !referencedImages.contains(image))
                .sorted()
                .toList();
        if (!unreferencedImages.isEmpty()) {
            throw new IOException("Invalid repository manifest: unreferenced prompt image "
                    + unreferencedImages.get(0));
        }
    }

    private static void validatePromptDiagramMetadata(String problemName, String file, String caption)
            throws IOException {
        if (!isPromptImage(file)) {
            throw new IOException("Invalid official prompt image reference in " + problemName
                    + ": prompt image file should use canonical p{problem}_...png name: " + file);
        }
        int problemNumber = topLevelProblemNumber(problemName);
        int imageProblemNumber = promptImageProblemNumber(file);
        if (problemNumber > 0 && imageProblemNumber != problemNumber) {
            throw new IOException("Invalid official prompt image reference in " + problemName
                    + ": prompt image file must belong to p" + problemNumber + ".json: " + file);
        }
        if (RESULT_OR_SOLUTION_DIAGRAM.matcher(file).matches()) {
            throw new IOException("Invalid official prompt image reference in " + problemName
                    + ": prompt image file should describe the prompt, not result/solution output: " + file);
        }
        if (caption == null || caption.isBlank()) {
            throw new IOException("Invalid official prompt image reference in " + problemName
                    + ": prompt image caption must not be blank for " + file);
        }
        // A labeled example state may show a valid result. Timing words such as
        // "after" are necessary for understanding operations on the same object.
        // Keep rejecting unlabeled outcomes and solution techniques below.
        if (RESULT_OR_SOLUTION_DIAGRAM.matcher(caption).matches()
                && !Pattern.compile("(?i).*(example|illustrat|rule).*").matcher(caption).matches()) {
            throw new IOException("Invalid official prompt image reference in " + problemName
                    + ": prompt image caption outcome must identify its example or rule context: " + caption);
        }
        if (SOLUTION_HINT_CAPTION.matcher(caption).matches()) {
            throw new IOException("Invalid official prompt image reference in " + problemName
                    + ": prompt image caption should not disclose solution technique: " + caption);
        }
    }

    private static CatalogIndex validateCatalogFile(String name, byte[] body) throws IOException {
        Catalog catalog;
        try {
            catalog = GSON.fromJson(new String(body, StandardCharsets.UTF_8), Catalog.class);
        } catch (RuntimeException e) {
            throw new IOException("Invalid official catalog JSON for " + name, e);
        }

        if (catalog == null || catalog.version == null || catalog.version.isBlank()) {
            throw invalidCatalog(name, "missing version");
        }
        if (catalog.tracks == null || catalog.tracks.isEmpty()) {
            throw invalidCatalog(name, "missing tracks");
        }

        Set<String> trackIds = new HashSet<>();
        Set<String> tags = new HashSet<>();
        Map<String, Set<String>> trackTagsById = new HashMap<>();
        for (int i = 0; i < catalog.tracks.size(); i++) {
            CatalogTrack track = catalog.tracks.get(i);
            if (track == null) {
                throw invalidCatalog(name, "tracks[" + i + "] must be an object");
            }
            if (track.id == null || track.id.isBlank()) {
                throw invalidCatalog(name, "tracks[" + i + "] missing id");
            }
            if (!track.id.matches("[a-z0-9]+(?:-[a-z0-9]+)*")) {
                throw invalidCatalog(name, "track id is not canonical: " + track.id);
            }
            if (!trackIds.add(track.id)) {
                throw invalidCatalog(name, "duplicate track id: " + track.id);
            }
            if (track.name == null || track.name.isBlank()) {
                throw invalidCatalog(name, "track name must not be blank: " + track.id);
            }
            if (track.tags == null || track.tags.isEmpty()) {
                throw invalidCatalog(name, "track tags must not be empty: " + track.id);
            }

            Set<String> trackTags = new HashSet<>();
            for (int j = 0; j < track.tags.size(); j++) {
                String tag = track.tags.get(j);
                if (tag == null || tag.isBlank()) {
                    throw invalidCatalog(name, "track tag must not be blank: " + track.id);
                }
                if (!trackTags.add(tag)) {
                    throw invalidCatalog(name, "duplicate tag in track " + track.id + ": " + tag);
                }
                if (!tags.add(tag)) {
                    throw invalidCatalog(name, "duplicate tag across tracks: " + tag);
                }
            }
            trackTagsById.put(track.id, trackTags);
        }

        return new CatalogIndex(tags, trackTagsById);
    }

    private static void validateCatalogReferences(List<DownloadedProblem> problems, CatalogIndex catalog)
            throws IOException {
        if (catalog == null) {
            return;
        }

        Map<String, Integer> tagProblemCounts = new HashMap<>();
        Map<String, Integer> trackProblemCounts = new HashMap<>();
        for (String tag : catalog.tags()) {
            tagProblemCounts.put(tag, 0);
        }
        for (String trackId : catalog.trackTags().keySet()) {
            trackProblemCounts.put(trackId, 0);
        }

        for (DownloadedProblem downloaded : problems) {
            List<String> tags = downloaded.problem().getTags();
            if (tags.isEmpty()) {
                throw new IOException("Invalid official problem JSON for " + downloaded.name()
                        + ": tags must be present when catalog.json is present");
            }
            Set<String> problemTags = new HashSet<>();
            for (String tag : tags) {
                if (tag == null || tag.isBlank()) {
                    throw new IOException("Invalid official problem JSON for " + downloaded.name()
                            + ": tags must not be blank when catalog.json is present");
                }
                if (!catalog.tags().contains(tag)) {
                    throw new IOException("Invalid official problem JSON for " + downloaded.name()
                            + ": tag is not present in catalog.json: " + tag);
                }
                if (!problemTags.add(tag)) {
                    throw new IOException("Invalid official problem JSON for " + downloaded.name()
                            + ": tags must not repeat catalog tag: " + tag);
                }
                tagProblemCounts.computeIfPresent(tag, (ignored, count) -> count + 1);
            }
            for (Map.Entry<String, Set<String>> track : catalog.trackTags().entrySet()) {
                if (track.getValue().stream().anyMatch(problemTags::contains)) {
                    trackProblemCounts.computeIfPresent(track.getKey(), (ignored, count) -> count + 1);
                }
            }
        }

        List<String> emptyTracks = trackProblemCounts.entrySet().stream()
                .filter(entry -> entry.getValue() == 0)
                .map(Map.Entry::getKey)
                .sorted()
                .toList();
        if (!emptyTracks.isEmpty()) {
            throw new IOException("Invalid official catalog JSON for catalog.json: catalog tracks must not be empty: "
                    + emptyTracks.getFirst());
        }

        List<String> unusedTags = tagProblemCounts.entrySet().stream()
                .filter(entry -> entry.getValue() == 0)
                .map(Map.Entry::getKey)
                .sorted()
                .toList();
        if (!unusedTags.isEmpty()) {
            throw new IOException("Invalid official catalog JSON for catalog.json: catalog tags must all be used by problems: "
                    + unusedTags.getFirst());
        }
    }

    private static IOException invalidCatalog(String name, String detail) {
        return new IOException("Invalid official catalog JSON for " + name + ": " + detail);
    }

    private static void validatePromptImage(String name, byte[] body) throws IOException {
        BufferedImage image = ImageIO.read(new ByteArrayInputStream(body));
        if (image == null || image.getWidth() <= 0 || image.getHeight() <= 0) {
            throw new IOException("Invalid official prompt image for " + name);
        }
        if (image.getWidth() < MIN_PROMPT_IMAGE_WIDTH || image.getHeight() < MIN_PROMPT_IMAGE_HEIGHT) {
            throw new IOException("Invalid official prompt image for " + name
                    + ": image must be at least " + MIN_PROMPT_IMAGE_WIDTH + "x" + MIN_PROMPT_IMAGE_HEIGHT
                    + " for IDE readability");
        }

        PromptImageStats stats = PromptImageStats.analyze(image);
        if (stats.opaquePixelRatio() < MIN_PROMPT_IMAGE_OPAQUE_PIXEL_RATIO) {
            throw new IOException("Invalid official prompt image for " + name
                    + ": prompt image must not be mostly transparent or empty");
        }
        if (stats.uniqueColors() < MIN_PROMPT_IMAGE_UNIQUE_COLORS) {
            throw new IOException("Invalid official prompt image for " + name
                    + ": prompt image must not be blank or flat");
        }
        if (stats.luminanceRange() < MIN_PROMPT_IMAGE_LUMINANCE_RANGE) {
            throw new IOException("Invalid official prompt image for " + name
                    + ": prompt image needs enough contrast for Minecraft GUI readability");
        }
    }

    private record PromptImageStats(int uniqueColors, int luminanceRange, double opaquePixelRatio) {
        static PromptImageStats analyze(BufferedImage image) {
            Set<Integer> colors = new HashSet<>();
            int minLuminance = 255;
            int maxLuminance = 0;
            int opaquePixels = 0;
            int sampledPixels = 0;
            int stepX = Math.max(1, image.getWidth() / 80);
            int stepY = Math.max(1, image.getHeight() / 80);

            for (int y = 0; y < image.getHeight(); y += stepY) {
                for (int x = 0; x < image.getWidth(); x += stepX) {
                    int argb = image.getRGB(x, y);
                    int alpha = (argb >>> 24) & 0xFF;
                    int red = (argb >>> 16) & 0xFF;
                    int green = (argb >>> 8) & 0xFF;
                    int blue = argb & 0xFF;
                    int luminance = (int) Math.round(0.2126 * red + 0.7152 * green + 0.0722 * blue);

                    sampledPixels++;
                    if (alpha > 0) {
                        opaquePixels++;
                    }
                    minLuminance = Math.min(minLuminance, luminance);
                    maxLuminance = Math.max(maxLuminance, luminance);
                    colors.add(argb);
                }
            }

            double opaqueRatio = sampledPixels == 0 ? 0.0 : opaquePixels / (double) sampledPixels;
            return new PromptImageStats(colors.size(), maxLuminance - minLuminance, opaqueRatio);
        }
    }

    private static void validateTranslationFile(String name, byte[] body) throws IOException {
        ProblemTranslationManager.ProblemTranslation translation;
        try {
            translation = GSON.fromJson(new String(body, StandardCharsets.UTF_8),
                    ProblemTranslationManager.ProblemTranslation.class);
        } catch (RuntimeException e) {
            throw new IOException("Invalid official translation JSON for " + name, e);
        }
        if (translation == null
                || (!translation.hasTitle()
                && !translation.hasDescription()
                && !translation.hasSolutions()
                && !translation.hasDiagrams())) {
            throw new IOException("Invalid official translation JSON for " + name);
        }
    }

    private static void validateChineseTranslations(List<DownloadedProblem> problems, Path stagingDir)
            throws IOException {
        for (DownloadedProblem downloaded : problems) {
            Problem problem = downloaded.problem();
            String translationName = "lang/zh_cn/p" + problem.getId() + ".json";
            Path translationPath = stagingDir.resolve(translationName);
            JsonObject translationJson;
            ProblemTranslationManager.ProblemTranslation translation;
            try {
                String translationText = Files.readString(translationPath, StandardCharsets.UTF_8);
                JsonElement parsed = JsonParser.parseString(translationText);
                if (!parsed.isJsonObject()) {
                    throw new IOException("Invalid official zh_cn translation JSON for " + translationName);
                }
                translationJson = parsed.getAsJsonObject();
                translation = GSON.fromJson(translationJson, ProblemTranslationManager.ProblemTranslation.class);
            } catch (RuntimeException e) {
                throw new IOException("Invalid official zh_cn translation JSON for " + translationName, e);
            }

            if (translation == null) {
                throw new IOException("Invalid official zh_cn translation JSON for " + translationName);
            }
            requireChineseText(translationName, "title", translation.getTitle(), problem.getTitle());
            String translatedDescription = translation.getDescription();
            requireChineseText(translationName, "description", translatedDescription, problem.getDescription());
            validateChineseProblemStatement(translationName, translatedDescription);

            List<Problem.Visual> visuals = problem.getVisuals();
            if (!visuals.isEmpty()) {
                List<ProblemTranslationManager.DiagramTranslation> translatedDiagrams = translation.getDiagrams();
                JsonArray translatedDiagramPayloads = requireChineseDiagramTranslationArray(translationName, translationJson);
                if (translatedDiagrams.size() != visuals.size()) {
                    throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                            + ": diagrams count must match " + downloaded.name());
                }
                if (translatedDiagramPayloads.size() != visuals.size()) {
                    throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                            + ": diagrams count must match " + downloaded.name());
                }
                for (int i = 0; i < visuals.size(); i++) {
                    Problem.Visual visual = visuals.get(i);
                    ProblemTranslationManager.DiagramTranslation translatedDiagram = translatedDiagrams.get(i);
                    if (translatedDiagram == null) {
                        throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                                + ": diagrams[" + i + "] must be an object");
                    }
                    JsonObject translatedDiagramPayload =
                            requireChineseDiagramTranslationObject(translationName, translatedDiagramPayloads, i);
                    validateChineseDiagramTranslationPayload(translationName, i, translatedDiagramPayload);
                    if (!visual.id().equals(translatedDiagram.getId())) {
                        throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                                + ": diagrams[" + i + "].id must match " + downloaded.name());
                    }
                    requireChineseText(translationName, "diagrams[" + i + "].caption",
                            translatedDiagram.getCaption(), visual.caption());
                }
            }

            List<Problem.Solution> solutions = problem.getSolutions();
            if (solutions.isEmpty()) {
                continue;
            }

            List<ProblemTranslationManager.SolutionTranslation> translatedSolutions = translation.getSolutions();
            JsonArray translatedSolutionPayloads = requireChineseSolutionTranslationArray(translationName, translationJson);
            if (translatedSolutions.size() != solutions.size()) {
                throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                        + ": solutions count must match " + downloaded.name());
            }
            if (translatedSolutionPayloads.size() != solutions.size()) {
                throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                        + ": solutions count must match " + downloaded.name());
            }
            for (int i = 0; i < solutions.size(); i++) {
                Problem.Solution solution = solutions.get(i);
                ProblemTranslationManager.SolutionTranslation translatedSolution = translatedSolutions.get(i);
                if (translatedSolution == null) {
                    throw new IOException("Invalid official zh_cn translation JSON for " + translationName
                            + ": solutions[" + i + "] must be an object");
                }
                JsonObject translatedSolutionPayload =
                        requireChineseSolutionTranslationObject(translationName, translatedSolutionPayloads, i);
                validateChineseSolutionTranslationPayload(translationName, i, translatedSolutionPayload);
                requireChineseText(translationName, "solutions[" + i + "].name",
                        translatedSolution.getName(), solution.getName());
                String translatedSolutionDescription = translatedSolution.getDescription();
                requireChineseText(translationName, "solutions[" + i + "].description",
                        translatedSolutionDescription, solution.getDescription());
                validateChineseSolutionStatement(translationName, i, translatedSolutionDescription);
            }
        }
    }

    private static JsonArray requireChineseSolutionTranslationArray(String name, JsonObject translationJson)
            throws IOException {
        if (!translationJson.has("solutions") || !translationJson.get("solutions").isJsonArray()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": solutions must be an array");
        }
        return translationJson.getAsJsonArray("solutions");
    }

    private static JsonArray requireChineseDiagramTranslationArray(String name, JsonObject translationJson)
            throws IOException {
        if (!translationJson.has("diagrams") || !translationJson.get("diagrams").isJsonArray()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": diagrams must be an array");
        }
        return translationJson.getAsJsonArray("diagrams");
    }

    private static JsonObject requireChineseSolutionTranslationObject(String name, JsonArray solutions, int index)
            throws IOException {
        JsonElement element = solutions.get(index);
        if (!element.isJsonObject()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": solutions[" + index + "] must be an object");
        }
        return element.getAsJsonObject();
    }

    private static JsonObject requireChineseDiagramTranslationObject(String name, JsonArray diagrams, int index)
            throws IOException {
        JsonElement element = diagrams.get(index);
        if (!element.isJsonObject()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": diagrams[" + index + "] must be an object");
        }
        return element.getAsJsonObject();
    }

    private static void validateChineseSolutionTranslationPayload(String name, int index, JsonObject solution)
            throws IOException {
        if (solution.has("code") || solution.has("language")) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": solutions[" + index + "] must translate text only and must not include code or language");
        }
    }

    private static void validateChineseDiagramTranslationPayload(String name, int index, JsonObject diagram)
            throws IOException {
        if (diagram.has("file")) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": diagrams[" + index + "] must translate text only and must not include file");
        }
    }

    private static void validateChineseProblemStatement(String name, String description) throws IOException {
        if (!description.startsWith("# ")) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": description must keep the markdown title heading");
        }
        if (!hasLocalizedExampleHeading(description)) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": description must include a localized ## 示例 section");
        }
        if (!hasLocalizedConstraintsHeading(description)) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": description must include a localized ## 约束 section");
        }
        if (ENGLISH_TRANSLATION_SECTION_HEADER.matcher(description).find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": description must not keep English Example/Constraints headings");
        }
        int problemNumber = translationProblemNumber(name);
        if (problemNumber <= TEXTBOOK_REVIEWED_PROBLEM_COUNT
                && SMART_QUOTE_IN_CODE_EXAMPLE.matcher(description).find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": description code examples must use ASCII quotes and separators");
        }
    }

    private static void validateChineseSolutionStatement(String name, int index, String description)
            throws IOException {
        if (!hasLocalizedApproachSection(description)) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": solutions[" + index + "].description must include a localized ## 思路 section");
        }
        if (ENGLISH_SOLUTION_SECTION_HEADER.matcher(description).find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": solutions[" + index + "].description must not keep English solution headings");
        }
    }

    private static boolean hasLocalizedExampleHeading(String value) {
        return value.contains("## 示例") || value.contains("## 绀轰緥");
    }

    private static boolean hasLocalizedConstraintsHeading(String value) {
        return value.contains("## 约束") || value.contains("## 绾︽潫");
    }

    private static boolean hasLocalizedApproachSection(String value) {
        return value.contains("## 思路") || value.contains("## 鎬濊矾");
    }

    private static void requireChineseText(String name, String field, String value, String originalValue)
            throws IOException {
        if (value == null || value.isBlank()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " must not be blank");
        }
        if (!CJK.matcher(value).find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " must contain Chinese text");
        }
        if (originalValue != null && !originalValue.isBlank() && value.strip().equals(originalValue.strip())) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " falls back to the original text");
        }
        if (looksLikeMojibake(value)) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " appears to contain mojibake");
        }
        if (QUESTION_MARK_PLACEHOLDER.matcher(value).find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " appears to contain placeholder question marks");
        }
        if (INLINE_CODE_PLACEHOLDER.matcher(value).find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " appears to contain inline code placeholder");
        }
        Matcher untranslatedEnglish = KNOWN_UNTRANSLATED_ENGLISH.matcher(value);
        if (untranslatedEnglish.find()) {
            throw new IOException("Invalid official zh_cn translation JSON for " + name
                    + ": " + field + " contains untranslated English phrase: "
                    + untranslatedEnglish.group());
        }
    }

    private static boolean looksLikeMojibake(String value) {
        return MOJIBAKE_FRAGMENTS.stream().anyMatch(value::contains);
    }

    private static void validateFileEntry(ManifestFile file) throws IOException {
        if (file == null || file.name == null || file.name.isBlank() || file.hash == null || file.hash.isBlank()) {
            throw new IOException("Invalid manifest file entry");
        }
        if (!file.hash.matches("[0-9a-f]{64}")) {
            throw new IOException("Invalid manifest hash for " + file.name);
        }
        if (file.size <= 0) {
            throw new IOException("Invalid manifest size for " + file.name);
        }
        if (file.size > maxFileSizeFor(file.name)) {
            throw new IOException("Manifest file " + file.name + " exceeds maximum size of "
                    + maxFileSizeFor(file.name) + " bytes: " + file.size);
        }
        if (!file.name.matches("p\\d+\\.json")
                && !file.name.equals("catalog.json")
                && !file.name.matches("lang/[a-z]{2}_[a-z]{2}/p\\d+\\.json")
                && !isPromptImage(file.name)) {
            throw new IOException("Unsupported manifest file entry: " + file.name);
        }
    }

    private static long maxFileSizeFor(String name) {
        return MAX_REPOSITORY_FILE_BYTES;
    }

    private static int compareManifestOrder(String left, String right) throws IOException {
        int leftGroup = manifestOrderGroup(left);
        int rightGroup = manifestOrderGroup(right);
        if (leftGroup != rightGroup) {
            return Integer.compare(leftGroup, rightGroup);
        }
        if (leftGroup == 1) {
            return Integer.compare(topLevelProblemNumber(left), topLevelProblemNumber(right));
        }
        return left.compareTo(right);
    }

    private static int manifestOrderGroup(String name) {
        if (isCatalogFile(name)) {
            return 0;
        }
        if (name.matches("p\\d+\\.json")) {
            return 1;
        }
        if (isPromptImage(name)) {
            return 2;
        }
        if (isTranslationFile(name)) {
            return 3;
        }
        return 4;
    }

    private static int topLevelProblemNumber(String name) throws IOException {
        if (!name.matches("p\\d+\\.json")) {
            return -1;
        }
        String digits = name.substring(1, name.length() - ".json".length());
        int number;
        try {
            number = Integer.parseInt(digits);
        } catch (NumberFormatException e) {
            throw new IOException("Invalid official problem file entry: " + name, e);
        }
        if (number <= 0 || !name.equals("p" + number + ".json")) {
            throw new IOException("Invalid official problem file entry: " + name);
        }
        return number;
    }

    private static boolean isTranslationFile(String name) {
        return name.matches("lang/[a-z]{2}_[a-z]{2}/p\\d+\\.json");
    }

    private static boolean isChineseTranslationFile(String name) {
        return name.matches("lang/zh_cn/p\\d+\\.json");
    }

    private static boolean isCatalogFile(String name) {
        return "catalog.json".equals(name);
    }

    private static boolean isPromptImage(String name) {
        return PROMPT_IMAGE_FILE.matcher(name).matches();
    }

    private static int promptImageProblemNumber(String name) throws IOException {
        Matcher matcher = PROMPT_IMAGE_FILE.matcher(name);
        if (!matcher.matches()) {
            return -1;
        }
        int number;
        try {
            number = Integer.parseInt(matcher.group(1));
        } catch (NumberFormatException e) {
            throw new IOException("Invalid official prompt image file entry: " + name, e);
        }
        if (number <= 0 || !name.startsWith("images/p" + number + "_")) {
            throw new IOException("Invalid official prompt image file entry: " + name);
        }
        return number;
    }

    private static int translationProblemNumber(String name) throws IOException {
        if (!isTranslationFile(name)) {
            return -1;
        }
        String fileName = name.substring(name.lastIndexOf('/') + 1);
        String digits = fileName.substring(1, fileName.length() - ".json".length());
        int number;
        try {
            number = Integer.parseInt(digits);
        } catch (NumberFormatException e) {
            throw new IOException("Invalid official translation file entry: " + name, e);
        }
        if (number <= 0 || !fileName.equals("p" + number + ".json")) {
            throw new IOException("Invalid official translation file entry: " + name);
        }
        return number;
    }

    private static void replaceDirectory(Path stagingDir, Path targetDir) throws IOException {
        replaceDirectory(stagingDir, targetDir, RemoteRepositoryDownloader::moveDirectory);
    }

    static void replaceDirectoryForTest(Path stagingDir, Path targetDir, DirectoryMover mover) throws IOException {
        replaceDirectory(stagingDir, targetDir, mover);
    }

    private static void replaceDirectory(Path stagingDir, Path targetDir, DirectoryMover mover) throws IOException {
        Path parentDir = targetDir.getParent();
        Path backupDir = null;
        boolean targetMovedToBackup = false;
        boolean preserveBackup = false;

        try {
            if (Files.exists(targetDir)) {
                backupDir = Files.createTempDirectory(parentDir, targetDir.getFileName() + ".backup-");
                Files.delete(backupDir);
                mover.move(targetDir, backupDir);
                targetMovedToBackup = true;
            }

            mover.move(stagingDir, targetDir);

            if (backupDir != null) {
                deleteRecursively(backupDir);
                backupDir = null;
            }
        } catch (IOException e) {
            if (targetMovedToBackup && backupDir != null && Files.exists(backupDir)) {
                try {
                    if (Files.exists(targetDir)) {
                        deleteRecursively(targetDir);
                    }
                    mover.move(backupDir, targetDir);
                    backupDir = null;
                } catch (IOException rollbackError) {
                    preserveBackup = true;
                    e.addSuppressed(rollbackError);
                    throw e;
                }
            }
            throw e;
        } finally {
            if (backupDir != null && !preserveBackup) {
                deleteRecursively(backupDir);
            }
        }
    }

    private static void moveDirectory(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, target);
        }
    }

    private static void deleteRecursively(Path path) throws IOException {
        if (path == null || !Files.exists(path)) {
            return;
        }
        try (var stream = Files.walk(path)) {
            stream.sorted(Comparator.reverseOrder())
                    .forEach(entry -> {
                        try {
                            Files.deleteIfExists(entry);
                        } catch (IOException e) {
                            throw new DeleteFailure(e);
                        }
                    });
        } catch (DeleteFailure e) {
            throw e.cause;
        }
    }

    private static final class DeleteFailure extends RuntimeException {
        private final IOException cause;

        private DeleteFailure(IOException cause) {
            super(cause);
            this.cause = cause;
        }
    }

    static String sha256(byte[] bytes) throws IOException {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(bytes));
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("SHA-256 is not available", e);
        }
    }

    private record RepositoryLocation(URI manifestUri, URI baseUri) {
        static RepositoryLocation from(String repositoryUrl) {
            if (repositoryUrl == null || repositoryUrl.isBlank()) {
                throw new IllegalArgumentException("Repository URL must not be blank");
            }

            String normalized = repositoryUrl.trim();
            if (normalized.endsWith("/")) {
                normalized = normalized.substring(0, normalized.length() - 1);
            }

            normalized = normalizeGitHubUrl(normalized);

            RepositoryLocation location;
            if (normalized.endsWith("/manifest.json")) {
                URI manifest = URI.create(normalized);
                String base = normalized.substring(0, normalized.length() - "/manifest.json".length());
                location = new RepositoryLocation(manifest, URI.create(base + "/"));
            } else {
                location = new RepositoryLocation(
                        URI.create(normalized + "/manifest.json"),
                        URI.create(normalized + "/")
                );
            }

            validateRemoteHttpUri(location.manifestUri);
            validateRemoteHttpUri(location.baseUri);
            return location;
        }

        URI fileUri(String name) {
            return baseUri.resolve(name);
        }

        private static String normalizeGitHubUrl(String url) {
            URI uri = URI.create(url);
            if (!"https".equalsIgnoreCase(uri.getScheme())
                    || !"github.com".equalsIgnoreCase(uri.getHost())) {
                return url;
            }

            String rawPath = uri.getRawPath();
            if (rawPath == null || rawPath.equals("/") || !rawPath.startsWith("/")) {
                return url;
            }

            String[] parts = rawPath.substring(1).split("/");
            if (parts.length < 2) {
                return url;
            }

            String owner = parts[0];
            String repo = parts[1];
            if (parts.length >= 5 && "tree".equals(parts[2])) {
                return rawGitHubContentUrl(owner, repo, parts, 3);
            }
            if (parts.length >= 5 && "blob".equals(parts[2])) {
                String rawUrl = rawGitHubContentUrl(owner, repo, parts, 3);
                if (!rawUrl.endsWith("/manifest.json")) {
                    throw new IllegalArgumentException(
                            "GitHub blob repository URL must point to manifest.json: " + url);
                }
                return rawUrl;
            }

            return "https://raw.githubusercontent.com/" + owner + "/" + repo + "/main/question_bank/official";
        }

        private static String rawGitHubContentUrl(String owner, String repo, String[] parts, int branchIndex) {
            String branch = parts[branchIndex];
            List<String> path = new ArrayList<>();
            for (int i = branchIndex + 1; i < parts.length; i++) {
                if (!parts[i].isBlank()) {
                    path.add(parts[i]);
                }
            }
            if (path.isEmpty()) {
                throw new IllegalArgumentException("GitHub repository URL must include a repository path");
            }
            return "https://raw.githubusercontent.com/" + owner + "/" + repo + "/" + branch + "/"
                    + String.join("/", path);
        }

        private static void validateRemoteHttpUri(URI uri) {
            String scheme = uri.getScheme();
            if (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme)) {
                throw new IllegalArgumentException("Repository URL must use http or https: " + uri);
            }
            if (uri.getHost() == null || uri.getHost().isBlank()) {
                throw new IllegalArgumentException("Repository URL must include a host: " + uri);
            }
        }
    }

    private static class Manifest {
        int totalProblems;
        String signature;
        List<ManifestFile> files;
    }

    private static class ManifestFile {
        String name;
        String hash;
        long size;
    }

    private static class Catalog {
        String version;
        List<CatalogTrack> tracks;
    }

    private static class CatalogTrack {
        String id;
        String name;
        List<String> tags;
    }

    private record CatalogIndex(Set<String> tags, Map<String, Set<String>> trackTags) {
    }

    private record DownloadedProblem(String name, Problem problem) {
    }
